```python
def partition_sum(nums):
    n = len(nums)
    if n < 2:
        return None
    if sum(nums) % 2 != 0:
        return None

    dp = [[0 for _ in range(n + 1)] for _ in range(n + 1)]

    # 初始化
    for i in range(n):
        dp[i][0] = nums[i]

    # 填充dp表
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            # 如果将nums[i]加入第一个子集，则第一个子集的和为j，第二个子集的和为i - j
            # 如果两个子集的和相等，则第二个子集的和为i/2
            if (j + nums[i]) % 2 == 0:
                dp[i][j] = dp[i-1][j]
