package main

import "fmt"

func mostFrequentString(strArray []string) string {
    if len(strArray) == 0 {
        return ""
    }

    // Count the frequency of each string
    frequencyMap := make(map[string]int)
    for _, s := range strArray {
        frequencyMap[s]++
    }

    // Find the string with the highest frequency
    maxFreq := 0
    mostFrequentString := ""

    for str, count := range frequencyMap {
        if count > maxFreq {
            maxFreq = count
            mostFrequentString = str
        } else if count == maxFreq {
            // If frequencies are equal, return any one of them
            mostFrequentString = str
        }
    }

    return mostFrequentString
}

