def find_pairs_with_diff(num_list, target):
    num_list = list(num_list)
    if len(num_list) < 2:
        return []

    pairs = []
    for i in range(len(num_list)):
        for j in range(i + 1, len(num_list)):
            if num_list[i] - num_list[j] == target:
                pairs.append([num_list[i], num_list[j]])

    return pairs
```

