    for (let i = 0; i < path.length; i++) {
        // 如果当前路径节点存在，则更新它
        if (current.hasOwnProperty(path[i])) {
            current = current[path[i]];
        } else {
            // 如果路径节点不存在，则返回未定义
            return undefined;
        }
    }

    // 返回指定字段的路径值
