class ResourceAllocationSystem:
    def __init__(self):
        self.resources = {'CPU': 1, 'Memory': 2, 'Storage': 10, 'Network': 5}
        self.allocation = {}

    def allocate(self, resource, amount):
        if amount > self.resources[resource]:
            amount = self.resources[resource]
        self.allocation[resource] = self.allocation.get(resource, 0) + amount
        return amount

