func isPrime(n: Int) -> Bool {
    // 首先，检查 n 是否为 1 或大于 n 的情况
    if n <= 1 {
        return false
    }

    // 检查 n 是否为质数
    // 如果 n 能被 2 整除，则它不是质数
    if n % 2 == 0 {
        return false
    }

    // 检查 n 在质数范围内的所有偶数（即 4, 6, 8, 10, 12, 14...）
    // 直到 n 的平方根
    for i in 3 ..< Int.sqrt(n) {
        if n % i == 0 {
            return false
        }
    }

    // 如果检查完所有可能的因子，则 n 是质数
    return true
}

