public static String convertToFirstPerson(String originalSentence) {
    if (originalSentence == null || originalSentence.isEmpty()) {
        return originalSentence;
    }

    StringBuilder newSentence = new StringBuilder();
    String[] words = originalSentence.split(" ");

    for (int i = 0; i < words.length; i++) {
        newSentence.append(words[i]).append(" ");
    }

    newSentence.setLength(newSentence.length() - 1); // 去掉末尾的空白字符
    return newSentence.toString();
}
