```javascript
function isPrime(num) {
    // 如果数字小于2，则它不是质数
    if (num < 2) {
        return false;
    }

    // 检查是否被2或更大的偶数整除
    if (num % 2 === 0) {
        return false;
    }

    // 从5到sqrt(num)检查是否有因子
    let i = 3;
    while (i <= Math.sqrt(num)) {
        if (num % i === 0) {
            return false;
        }
        i += 2;
    }

    // 如果所有检查都通过，则它是质数
    return true;
}

