```java
public int longestDistinctSubstring(String s) {
    int maxLength = 0;
    int left = 0;
    int right = 0;
    int[] lastSeen = new int[s.length() + 1];

    // 初始化窗口
    right = 0;
    while (right < s.length()) {
        // 检查当前字符是否已出现
        if (lastSeen[s.charAt(right)] != -1) {
            // 滑动窗口，移除左边多余的字符
            left++;
            lastSeen[s.charAt(left)] = -1;
        }

        // 更新最大长度
        maxLength = Math.max(maxLength, right - left + 1);

        // 扩大窗口
        right++;
    }

    return maxLength;
}
```

