import java.util.Scanner;

public class SquareRootNewtonRaphson {

    public static double squareRoot(double number) {
        // Error handling for non-positive input
        if (number <= 0) {
            System.out.println("The square root of a non-positive number is not defined.");
            return 0;
        }

        // Initialize the Newton-Raphson method
        double x = number;
        double tolerance = 1e-5;

        // Newton-Raphson iterations
        while (Math.abs(x - Math.sqrt(number)) > tolerance) {
            x = (x + number / x) / 2;
        }

        return x;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Prompt the user for input
        System.out.print("Enter a positive number: ");
        double number = scanner.nextDouble();

        // Calculate the square root using Newton-Raphson method
        double result = squareRoot(number);

        // Display the result
        System.out.println("The square root of the number is " + result);
    }
}
```

