```java
public static String reverseSentence(String sentence) {
    if (sentence == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    char[] chars = sentence.toCharArray();

    // 反转字符数组
    for (int i = chars.length - 1; i >= 0; i--) {
        result.append(chars[i]);
    }

    // 反转字符串
    return result.toString();
}
```

