```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using OpenNLP;

class WordExtractor
{
    private static readonly WordTokenizer tokenizer = new WordTokenizer();

    public static string SecondLongestWord(string text, string stopWords = "the, and")
    {
        // 1. 分词
        var words = tokenizer.Tokenize(text);

        // 2. 过滤掉停止词
        var filteredWords = words.Where(w => !stopWords.Contains(w)).ToArray();

        // 3. 排序并取第二长的单词
        if (filteredWords.Length < 2)
            return string.Empty;

        var longestWord = filteredWords.OrderByDescending(w => w.Length).FirstOrDefault();
        var secondLongestWord = filteredWords.OrderByDescending(w => w.Length).FirstOrDefault();

        return secondLongestWord?.ToString() ?? string.Empty;
    }
}
```

