```typescript
class HashRing {
  private hash: number;
  private value: number;
  private count: number;

  constructor(value: number) {
    this.value = value;
    this.count = 0;
    this.hash = this.generateHash();
  }

  private generateHash(): number {
    let hash = 5;
    for (let i = 0; i < 8; i++) {
      hash = ((hash ^ this.value) % 256) + hash;
    }
    return hash;
  }

  getHash(): number {
    return this.hash;
  }

  increment(): void {
    this.hash = this.generateHash();
    this.count++;
  }
}
```

