要使用 JavaScript 发起 HTTP 请求，你可以利用 browser 的 XMLHttpRequest 对象。以下是创建 HTTP 请求的示例代码：

```javascript
var xhr = new XMLHttpRequest();

xhr.open('GET', 'https://api.example.com/data');

xhr.onload = function() {
  if (xhr.status == 200) {
    var data = JSON.parse(xhr.responseText);
    console.log(data);
  }
};

