```javascript
function findMedianArray(array) {
    // Check if the array is empty
    if (array.length === 0) {
        throw new Error("The array cannot be empty.");
    }

    // Sort the array in ascending order
    sortedArray = array.sort();

    // Check if the number of elements is odd or even
    let count = sortedArray.length;
    let median;

    // If the number of elements is odd, the median is the middle element
    // If the number of elements is even, the median is the average of the two middle elements
    if (count % 2 === 1) {
        median = sortedArray[count / 2];
    } else {
        median = (sortedArray[count / 2 - 1] + sortedArray[count / 2]) / 2;
    }

    return median;
}

